            "nodes": [
              {"kind":"line","speaker":"Foam Finger Fan","mood":"bold","text":"TOP SHELF! TOP SHELF! {pause} Oh, you're the hoodie. {small}Hoodie! Hoodie!{/small}","id":"s10.residents.foam-finger-fan.0"},
              {"kind":"line","speaker":"Foam Finger Fan","mood":"neutral","text":"I've got two foam fingers. One for each side. I like to win.","id":"s10.residents.foam-finger-fan.1"},
            ],
            "note": "generic, foam_finger",
